import java.time.Duration;
import java.util.List;

public class EmptyCartTest extends BaseTest {

    @Test
    public void testEmptyCartContainingAProduct() {
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        Home home = new Home(driver);
        TopNavBar topNavBar = new TopNavBar(driver);

        home.goHome();

        // Verify initial state: cart item count is zero
        int initialCartCount = topNavBar.getCartCount();
        Assert.assertEquals("Expected fresh browser session to have an empty cart", 0, initialCartCount);

        // Check that at least one product is available to add to cart
        List<WebElement> addToCartButtons = driver.findElements(By.cssSelector("button.btn-add-to-cart, a.btn-add-to-cart, .product-item .btn, [data-test='add-to-cart']"));
        Assert.assertFalse("Expected at least one published seed product available on the home page", addToCartButtons.isEmpty());

        // When the customer adds one product to the cart
        home.addToCart(0);

        // And opens the cart view
        topNavBar.openCart();

        // Then the cart contains one item
        wait.until(ExpectedConditions.visibilityOfElementLocated(By.cssSelector("#cart, .cart-sidebar, .cart-drawer, [data-test='cart-view']")));
        Assert.assertEquals("Cart count should reflect 1 item", 1, topNavBar.getCartCount());

        // When the customer clicks the empty cart button
        By emptyCartBtnLocator = By.cssSelector("#empty-cart, .btn-empty-cart, button[data-action='empty-cart'], #btn-empty-cart");
        WebElement emptyCartButton = wait.until(ExpectedConditions.elementToBeClickable(emptyCartBtnLocator));
        emptyCartButton.click();

        // Then the confirmation modal is displayed
        By modalLocator = By.cssSelector(".modal.show, .modal-dialog, #confirm-empty-cart-modal, [data-test='confirm-empty-modal']");
        WebElement modal = wait.until(ExpectedConditions.visibilityOfElementLocated(modalLocator));
        Assert.assertTrue("Confirmation modal should be displayed", modal.isDisplayed());

        // When the customer confirms the empty-cart action
        By confirmBtnLocator = By.cssSelector(".modal.show button.btn-danger, .modal.show .btn-confirm, #confirm-empty-cart, [data-test='confirm-empty-cart-btn']");
        WebElement confirmButton = wait.until(ExpectedConditions.elementToBeClickable(confirmBtnLocator));
        confirmButton.click();

        // Then the cart view displays 'Cart empty'
        By emptyCartTextLocator = By.xpath("//*[contains(text(), 'Cart empty') or contains(text(), 'cart empty') or contains(text(), 'Cart is empty')]");
        WebElement emptyCartMsg = wait.until(ExpectedConditions.visibilityOfElementLocated(emptyCartTextLocator));
        Assert.assertTrue("Expected 'Cart empty' indicator in the cart view", emptyCartMsg.isDisplayed());

        // And the cart item count is zero
        wait.until(driver -> topNavBar.getCartCount() == 0);
        Assert.assertEquals("Cart item count should be zero", 0, topNavBar.getCartCount());

        // And the success notification says 'Cart successfully emptied'
        By notificationLocator = By.xpath("//*[contains(@class, 'alert') or contains(@class, 'toast') or contains(@class, 'notification')][contains(text(), 'Cart successfully emptied')]");
        WebElement notification = wait.until(ExpectedConditions.visibilityOfElementLocated(notificationLocator));
        Assert.assertTrue("Expected success notification saying 'Cart successfully emptied'", notification.isDisplayed());
        Assert.assertTrue("Notification text should contain expected message", notification.getText().contains("Cart successfully emptied"));

        // And the cart action buttons are hidden
        List<WebElement> checkoutBtns = driver.findElements(By.cssSelector("#checkout, .btn-checkout, [data-test='checkout-button']"));
        boolean anyCheckoutVisible = checkoutBtns.stream().anyMatch(WebElement::isDisplayed);
        Assert.assertFalse("Checkout and cart action buttons should be hidden when cart is empty", anyCheckoutVisible);
    }
}
